SELECT (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('pp','cc')) AS table_count, (SELECT quote(x)||':'||typeof(x) FROM pp) AS pp_row, (SELECT quote(y)||':'||typeof(y) FROM cc) AS cc_row, (SELECT "type"||':'||pk FROM pragma_table_info('pp') WHERE name='x') AS pp_column, (SELECT "type"||':'||pk FROM pragma_table_info('cc') WHERE name='y') AS cc_column, (SELECT count(*) FROM pragma_foreign_key_check) AS fk_violations, (SELECT "table"||':'||"from"||':'||"to"||':'||"on_update"||':'||"on_delete"||':'||"match" FROM pragma_foreign_key_list('cc')) AS fk_definition, (SELECT CASE WHEN lower(sql) LIKE '%deferrable initially deferred%' THEN 1 ELSE 0 END FROM sqlite_schema WHERE type='table' AND name='cc') AS is_deferred;